head.script:
scwin.checkHeight = function() {
    return WebSquare.wUnit.getJq("#ui_ck01_").height() <= 300 && WebSquare.wUnit.getJq("#ui_ch02_").height() <= 300;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭 또는 Property 탭에서 ui_ck01 의 style 부분을 확인한다.
    //1. Check the style part of ui_ck01 in the Source tab or Property tab.
    //Verify step 1. style = "height: 300px;"
    //Test step 2. ui_ch02 의 style 부분을 확인한다.
    //2. Check the style part of ui_ch02.
    //Verify step 2. style = "width: 100%; height: 300px;"
    //Test step 3. 브라우저에서 확인한다.
    //3. Check in the browser.
    //Verify step 3. Editor Width and Height are normally displayed. (In previous versions, horizontal scrolling occurred and the height was set larger than the set height)
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("assert", "scwin.checkHeight()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 03-Apr-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
